<?php $researchEvidence=$meta['evidence']??null; ?>
<details class="research-disclosure evidence-panel" id="research-evidence" data-evidence-panel>
<summary>Research evidence<?php if($researchEvidence): ?> · <?=e(count($researchEvidence['claims']))?> claims · <?=e(count($researchEvidence['sources']))?> sources<?php endif ?></summary>
<?php if(!$researchEvidence): ?><p>This historical result has no structured claim-to-source evidence record. No source inspections or claim assessments have been inferred.</p>
<?php else: ?>
<p class="fine">Source access, quotations and scientific assessments are contributor declarations. Platform checks validate structure and references; an independent review assesses source support.</p>
<h2>Scope and search</h2><?=prose($researchEvidence['scope'])?><p><strong>Stopping rule:</strong> <?=e($researchEvidence['stopping_rule'])?></p>
<?php foreach($researchEvidence['search_log'] as $search): ?><article class="ledger-entry"><h3><?=e($search['query'])?></h3><p><strong>Where:</strong> <?=e($search['where'])?></p><?=prose($search['result'])?></article><?php endforeach ?>
<h2>Claims and supporting passages</h2><?php if(!$researchEvidence['claims']): ?><p>This packet makes no structured research conclusions. Read its planning scope and evidence needs.</p><?php endif ?>
<?php foreach($researchEvidence['claims'] as $claim): ?>
<article class="task-brief evidence-claim" id="claim-<?=e($claim['id'])?>"><h3>Claim <?=e($claim['id'])?> · <?=e($claim['kind'])?></h3><?=prose($claim['statement'])?>
<p><span class="status"><?=e($claim['support'])?></span> · <?=e($claim['confidence'])?> confidence</p><?=prose($claim['confidence_reason'])?>
<?php if($claim['derivation']): ?><p><strong>Interpretation or proposal:</strong> <?=e($claim['derivation'])?></p><?php endif ?>
<p><strong>Limitations:</strong> <?=e($claim['limitations'])?></p><p><strong>Contrary evidence and alternatives:</strong> <?=e($claim['counterevidence'])?></p>
<?php foreach($claim['links'] as $link): ?><div class="ledger-entry"><p><a href="#source-<?=e($link['source_id'])?>">Source <?=e($link['source_id'])?></a> · <?=e($link['relation'])?> · <?=e($link['locator'])?></p><?php if($link['excerpt']): ?><blockquote><?=e($link['excerpt'])?></blockquote><?php endif ?><?=prose($link['explanation'])?></div><?php endforeach ?>
<?php if($claim['basis_result_ids']): ?><p>Built on accepted results: <?php foreach($claim['basis_result_ids'] as $basisId): ?><a href="<?=e($base)?>/results/<?=e($basisId)?>"><?=e($basisId)?></a> <?php endforeach ?></p><?php endif ?>
</article><?php endforeach ?>
<h2>Source access record</h2><?php if(!$researchEvidence['sources']): ?><p>No sources were inspected; consult the search record and limitations.</p><?php endif ?>
<?php foreach($researchEvidence['sources'] as $source): ?><article class="ledger-entry" id="source-<?=e($source['id'])?>"><h3><?=e($source['id'])?> · <?=e($source['title'])?></h3><p><?=e($source['type'])?> · <?=e(str_replace('_',' ',$source['access']))?></p><?php if($source['url']): ?><p><a href="<?=e($source['url'])?>" rel="noreferrer"><?=e($source['url'])?></a></p><?php endif ?><?=prose($source['access_note'])?></article><?php endforeach ?>
<?php if($researchEvidence['datasets']??[]): ?><h2>Backing datasets</h2><ul><?php foreach($researchEvidence['datasets'] as $backingData): ?><li><?=e($backingData['title'])?> · <?=e($backingData['provenance'])?> · <?=count($backingData['rows'])?> rows. <?=e($backingData['uncertainty'])?></li><?php endforeach ?></ul><?php if($researchEvidence['artifacts']??[]): ?><a href="#visual-artifacts">Explore the linked visual artifacts and complete data tables</a><?php else: foreach($researchEvidence['datasets'] as $backingData): ra_table($backingData); endforeach; endif ?><?php endif ?>
<?php if($researchEvidence['artifact_reviews']??[]): ?><h2>Independent visual artifact audits</h2><?php foreach($researchEvidence['artifact_reviews'] as $visualAudit): ?><article class="task-brief"><h3><?=e($visualAudit['artifact_id'])?> · <?=e($visualAudit['verdict'])?></h3><?=prose($visualAudit['reason'])?><a href="<?=e($base)?>/results/<?=e($visualAudit['result_id'])?>#visual-artifacts">Reviewed result and visual specifications</a></article><?php endforeach; endif ?>
<?php if($researchEvidence['review_checks']): ?><h2>Independent claim audits</h2><?php foreach($researchEvidence['review_checks'] as $review): ?><article class="task-brief evidence-audit"><h3>Claim <?=e($review['claim_id'])?> · <?=e($review['verdict'])?></h3><p><a href="<?=e($base)?>/results/<?=e($review['result_id'])?>#claim-<?=e($review['claim_id'])?>">Read the reviewed result and claim</a></p><?=prose($review['reason'])?>
<?php foreach($review['source_checks'] as $inspection): ?><div class="ledger-entry"><p><strong>Source <?=e($inspection['source_id'])?></strong> · <?=e(str_replace('_',' ',$inspection['access']))?> · <?=e($inspection['locator'])?></p><?php if($inspection['excerpt']): ?><blockquote><?=e($inspection['excerpt'])?></blockquote><?php endif ?><?=prose($inspection['assessment'])?></div><?php endforeach ?></article><?php endforeach; endif ?>
<?php endif ?></details>
